use std::fs

fn main() {
    let text = fs::read_to_string("/dev/stdin").unwrap_or("")
    for line in text.lines() {
        let chars: Vec<char> = line.chars().collect()
        let n = chars.len()
        let mut fields: Vec<string> = []
        let mut cur = ""
        let mut inq = false
        let mut i = 0
        while i < n {
            let c = chars[i]
            if inq {
                if c == '"' {
                    if i + 1 < n && chars[i + 1] == '"' {
                        cur.push('"')
                        i += 1
                    } else {
                        inq = false
                    }
                } else {
                    cur.push(c)
                }
            } else if c == '"' {
                inq = true
            } else if c == ',' {
                fields.push(cur)
                cur = ""
            } else if c != '\r' {
                cur.push(c)
            }
            i += 1
        }
        fields.push(cur)
        let mut out = "${fields.len()}: "
        let mut k = 0
        while k < fields.len() {
            if k > 0 { out.push('|') }
            out.push_str("[")
            out.push_str(fields[k])
            out.push_str("]")
            k += 1
        }
        println(out)
    }
}

